using Azure;
using Azure.AI.OpenAI;
using Azure.Identity;
using Polly;
using Polly.Retry;

var credential = new DefaultAzureCredential();
var client = new OpenAIClient(
    new Uri("https://my-openai.openai.azure.com/"),
    credential);

// Define retry policy: 3 retries with exponential backoff
RetryPolicy retryPolicy = Policy
    .Handle<RequestFailedException>(ex => ex.Status == 429 || ex.Status >= 500)
    .WaitAndRetryAsync(3, retryAttempt =>
        TimeSpan.FromSeconds(Math.Pow(2, retryAttempt)));

var chatOptions = new ChatCompletionsOptions
{
    DeploymentName = "gpt4o",
    Messages = { new ChatMessage(ChatRole.User, "Explain Azure Functions.") }
};

// Execute with retry
var response = await retryPolicy.ExecuteAsync(async () =>
{
    var result = await client.GetChatCompletionsAsync(chatOptions);
    return result.Value;
});

Console.WriteLine(response.Choices[0].Message.Content);

targetScope = 'resourceGroup'

param location string = resourceGroup().location
param appName string

// App Service Plan
resource appServicePlan 'Microsoft.Web/serverfarms@2023-12-01' = {
  name: '${appName}-plan'
  location: location
  sku: { name: 'S1', capacity: 1 }
  kind: 'app'
}

// Web App with Managed Identity
resource webApp 'Microsoft.Web/sites@2023-12-01' = {
  name: appName
  location: location
  identity: { type: 'SystemAssigned' }
  properties: { serverFarmId: appServicePlan.id }
}

// Key Vault for secrets
resource keyVault 'Microsoft.KeyVault/vaults@2023-07-01' = {
  name: 'kv-${uniqueString(resourceGroup().id)}'
  location: location
  properties: {
    tenantId: subscription().tenantId
    sku: { name: 'standard' }
    enableRbacAuthorization: true
  }
}

// Grant web app access to Key Vault secrets
resource kvAccessPolicy 'Microsoft.Authorization/roleAssignments@2022-04-01' = {
  name: '${webApp.name}-kv-access'
  scope: keyVault
  properties: {
    roleDefinitionId: '${subscription().subscriptionId}/providers/Microsoft.Authorization/roleDefinitions/4633458b-17de-408a-b874-0445c86b69e6'
    principalId: webApp.identity.principalId
    principalType: 'ServicePrincipal'
  }
}
